-- 0423 contactos de ayuntamientos (DIR3, fichero oficial reutilizable) cruzados a codigo_ine.
-- Solo matches EXACTOS por nombre+provincia (la pasada difusa se descartó por falsos positivos, ej: Martorell/Martorellas).
DROP TABLE IF EXISTS ayuntamientos_contacto;
CREATE TABLE ayuntamientos_contacto (codigo_ine TEXT PRIMARY KEY, nombre_bdgel TEXT, cif TEXT, email TEXT, fuente TEXT DEFAULT 'dir3', fecha_carga TEXT DEFAULT (date('now')));
